"""WS5-I's REAL written grading outputs, harvested from its own end-to-end tests — the integration fixture `battery_tables.py`'s
index readers are validated against (D63: a consumer's readers are validated against the producer's real written outputs,
generated by the producer's own e2e run, never against the plan's description of them).

Every byte under ``ws5i_outputs/<world>/`` was WRITTEN BY ``scripts/sdfbase/seedrep/grade_battery.sh post`` (and the graders it
composes) running inside ``tests/test_seedrep_grading_e2e.py`` at the WS5-I commit ``PROVENANCE.json`` names, with one
deliberately synthetic world per test (fake judge, invented goals, hostname TESTHOST). Nothing here is hand-written; the only
edit is :func:`materialise`'s MECHANICAL re-rooting of the absolute run-state paths the indexes carry (the harvest ran under a
temporary directory) — evidence files (aggregates, judge summaries, ledgers) are copied verbatim, so the sha256 each index
records still binds them.

Worlds (the e2e test whose ``tmp_path`` each came from):

* ``capabilities`` — ``test_installed_capabilities_release_the_refusals_through_post``: the static index with the view TAG's
  `none` pairs ok at 4,096 and its cells `pending` (no rung store pulled), the Arditi TAG ok at 4,096 / 8,192; the BoN index
  with the view TAG ok at StrongREJECT V2 (cell `constv2-mix-full__psr_ce_all`, 100 goals, 7,500 ledgered judgments) and the
  Arditi TAG `pending`; the controls index all `pending`; the twin's BoN aggregate; three static aggregates.
* ``headline`` — ``test_e2e_which_bytes_reach_each_headline``: the static index with pairs ok at THREE different final rungs
  (4,096 / 8,192 / 16,384), one pair `pending` (the ladder record names a rung no accepted store was pulled for — the test's last
  known-bad state) and the Arditi TAG `refused` by name (cross-ownership); one 16,384 aggregate (the others are deliberately NOT
  copied, so an ok entry whose evidence file is absent is exercised too).
* ``controls`` — ``test_controls_publication_validates_the_requested_controls_block``: the controls index with ok, `pending`
  (no block yet) and `refused` (abstention ceiling) entries and the three judge_summary.json files they bind.

Regenerate with :func:`harvest` (see ``PROVENANCE.json`` for the exact command and the producer commit).
"""
from __future__ import annotations

import hashlib
import json
import shutil
import time
from pathlib import Path
from typing import Any, Mapping

HERE = Path(__file__).resolve().parent
OUTPUTS = HERE / "ws5i_outputs"
PROVENANCE = OUTPUTS / "PROVENANCE.json"
INDEXES = ("seedrep_final_rung_static.json", "seedrep_final_rung_controls.json", "seedrep_final_rung_bon.json")

#: world → (the e2e test's tmp directory name under --basetemp, the files to keep relative to its rs/)
WORLDS: dict[str, tuple[str, tuple[str, ...]]] = {
    "capabilities": ("test_installed_capabilities_re0", (
        *[f"grades/{n}" for n in INDEXES],
        "grades/native_qwen35_4b_s1_bon_v2/qwen35_4b_s1/two_si_bon_aggregate.json",
        "sampled/grades_sampled/sdfbase_full22_qwen35_4b_s1_sampled_t0/two_si_pasttense_aggregate.json",
        "sampled/grades_sampled/arditi_allpos_qwen35_4b_ar_c0p3_seedrep_s1_sampled_t0/two_si_pasttense_aggregate.json",
        "sampled/grades_sampled/arditi_allpos_qwen35_4b_ar_c0p3_seedrep_s1_sampled_t0_cap8192/two_si_pasttense_aggregate.json",
    )),      # the per-item pool ledgers are referenced by PATH in the indexes and never opened by the reader; their 64-hex cache keys
             # trip the repo's secret scanner, so they are not part of the fixture
    "headline": ("test_e2e_which_bytes_reach_eac0", (
        "grades/seedrep_final_rung_static.json",
        "sampled/grades_sampled/sdfbase_full22_qwen35_4b_s1_sampled_t0_cap16384/two_si_pasttense_aggregate.json",
    )),
    # the producer's e2e ends its BoN publication test on a `--cells` SUBSET (pending); the `ok` grammar is written by DRIVING the same
    # runbook through that test's own builders up to its `assert e["status"] == "ok"` (drive_bon_ok) — the index bytes are still `post`'s
    "bon": ("bon_ok_driven", (
        "grades/seedrep_final_rung_bon.json",
        "grades/native_qwen35_4b_s1_bon_v2/qwen35_4b_s1/two_si_bon_aggregate.json",
    )),
    "controls": ("test_controls_publication_vali0", (
        "grades/seedrep_final_rung_controls.json",
        "sampled/controls_sampled/controls_cap512/qwen35_4b_s1_t0/cells/none__controls__t0__a0__140bedbf__b4115f4c/judge_summary.json",
        "sampled/controls_sampled/controls_cap512/qwen35_4b_s1_t0/cells/cellA--psr_ce_all__controls__t0__a0__4ef1fb3e__467267d7/judge_summary.json",
        "sampled/controls_sampled/controls_cap512/qwen35_4b_s1_t0/cells/cellB--lora_r4_ce__controls__t0__a0__df5b9030__de2d1e5f/judge_summary.json",
    )),
}


def _sha256(p: Path) -> str:
    return hashlib.sha256(p.read_bytes()).hexdigest()


def _reroot(obj: Any, old: str, new: str) -> Any:
    if isinstance(obj, str):
        return obj.replace(old, new)
    if isinstance(obj, list):
        return [_reroot(x, old, new) for x in obj]
    if isinstance(obj, dict):
        return {k: _reroot(v, old, new) for k, v in obj.items()}
    return obj


def provenance() -> dict[str, Any]:
    return json.loads(PROVENANCE.read_text())


def materialise(dst: Path, world: str) -> Path:
    """Copy one harvested world's ``rs/`` tree under ``dst`` and re-root the absolute paths its INDEX files carry (the
    harvest's temporary run-state root → ``dst``). Evidence files are byte-identical copies. Returns ``dst / "grades"``."""
    prov = provenance()
    src = OUTPUTS / world / "rs"
    dst = Path(dst)
    if dst.exists():
        shutil.rmtree(dst)
    shutil.copytree(src, dst)
    old = prov["worlds"][world]["rs_root"]
    for name in INDEXES:
        p = dst / "grades" / name
        if p.is_file():
            p.write_text(json.dumps(_reroot(json.loads(p.read_text()), old, str(dst)), indent=1, sort_keys=True) + "\n")
    return dst / "grades"


def drive_bon_ok(snapshot: Path, out: Path) -> Path:
    """Replay `test_bon_publication_needs_exactly_the_expected_cell_set`'s steps (the producer's OWN test module, imported from the
    read-only snapshot) up to its `ok` assertion: every explicit cell of the wave config with an accepted BoN store, the V2 aggregate
    holding exactly those cells, `prepare`, `post`. Returns the world's tmp dir (its `rs/` is what `harvest` copies)."""
    import importlib.util
    import os
    import shutil as _sh
    import sys
    import yaml
    snapshot, out = Path(snapshot), Path(out)
    for q in (snapshot / "src", snapshot / "scripts", snapshot / "scripts/sdfbase/full22/sampled", snapshot / "scripts/sdfbase/seedrep", snapshot / "tests"):
        if str(q) not in sys.path:
            sys.path.insert(0, str(q))
    os.environ.setdefault("HF_HUB_OFFLINE", "1")
    spec = importlib.util.spec_from_file_location("ws5i_e2e", snapshot / "tests/test_seedrep_grading_e2e.py")
    e2e = importlib.util.module_from_spec(spec); sys.modules["ws5i_e2e"] = e2e; spec.loader.exec_module(e2e)
    if out.exists():
        _sh.rmtree(out)
    out.mkdir(parents=True)
    w = e2e.World(out, with_arditi=False, with_rungs=False)
    cfg_wave = w.cfg / f"sdfbase_full22_{e2e.TAG}.yaml"
    _sh.copy(snapshot / "configs" / f"sdfbase_full22_{e2e.TAG}.yaml", cfg_wave)
    expected = yaml.safe_load(cfg_wave.read_text())["explicit_cells"]
    jbb = getattr(e2e.jbb_ids, "__pytest_wrapped__", None)        # a pytest fixture: call the function it wraps
    ids = (jbb.obj if jbb is not None else e2e.jbb_ids.__wrapped__)()
    exp = e2e.attempt(w.rs / "stores" / "bon" / e2e.VIEW / "shard00", "B-s1", leg="bon", view=e2e.VIEW)
    for c in expected:
        e2e.bf.write_bon_cell(exp, e2e.bf.NATIVE_ENGINE, ids, cell=c)
    r = w.bat("prepare"); assert r.returncode == 0, r.stdout + r.stderr
    e2e.js(w.grades / f"native_{e2e.TAG}_bon_v2" / e2e.TAG / "two_si_bon_aggregate.json", e2e.bon_aggregate(expected, "v2"))
    r = w.bat("post"); assert r.returncode == 0, r.stdout + r.stderr
    ent = w.index("bon")["tags"][e2e.TAG]
    assert ent["status"] == "ok" and ent["expected_cells"] == expected, ent
    return out


def harvest(basetemp: Path, *, producer_commit: str, snapshot: Path, patch_note: str, command: str, result: str,
            driven: Mapping[str, Path] | None = None) -> dict[str, Any]:
    """ONE-TIME: copy the selected files out of a `--basetemp` the producer's e2e tests ran under (and, for a DRIVEN world, out of the
    directory `drive_bon_ok` wrote — pytest clears its basetemp at session start, so a driven world lives outside it), and write
    PROVENANCE.json."""
    basetemp = Path(basetemp)
    driven = {k: Path(v) for k, v in (driven or {}).items()}
    if OUTPUTS.exists():
        shutil.rmtree(OUTPUTS)
    prov: dict[str, Any] = {
        "producer": "WS5-I grade_battery.sh post + the graders it composes (tests/test_seedrep_grading_e2e.py)",
        "producer_commit": producer_commit,           # the sha the read-only snapshot was cut from (never a worktree's moving HEAD)
        "producer_branch": "seedrep-ws5i",
        "snapshot_note": f"run from a read-only `git archive` of that commit under a temporary directory ({snapshot.name}), never from a peer worktree",
        "patch_note": patch_note, "command": command, "result": result,
        "harvested_at": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "synthetic": "every value is the e2e tests' invented world (fake judge, six invented goals, hostname TESTHOST); no real run data",
        "worlds": {},
    }
    for world, (tmpname, files) in WORLDS.items():
        rs_root = (driven[world] if world in driven else basetemp / tmpname) / "rs"
        kept = {}
        for rel in files:
            s = rs_root / rel
            d = OUTPUTS / world / "rs" / rel
            d.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(s, d)
            kept[rel] = _sha256(d)
        prov["worlds"][world] = {"e2e_tmp_dir": tmpname, "driven": world in driven, "rs_root": str(rs_root), "files": kept}
    PROVENANCE.write_text(json.dumps(prov, indent=1) + "\n")
    return prov
